mapper.select:
select from ry_business.ry_rental_after_sales_case c inner join ry_business.ry_rental_order o on o.order_id = c.order_id and o.tenant_id = c.tenant_id and o.member_id = c.member_id and o.is_delete = 0 where c.tenant_id = #{tenantId} and c.member_id = #{memberId} and c.is_delete = 0
and c.case_status = #{query.caseStatus}
and o.order_no = #{query.orderNo}
and (c.case_no like concat('%', #{query.keyword}, '%') or o.order_no like concat('%', #{query.keyword}, '%') or c.problem_desc like concat('%', #{query.keyword}, '%'))
order by c.create_time desc, c.case_id desc

select count(1)
from ry_business.ry_rental_after_sales_case c
where c.tenant_id = #{tenantId}
  and c.member_id = #{memberId}
  and c.order_id = #{orderId}
  and c.case_status = 0
  and c.is_delete = 0

mapper.update:
update ry_business.ry_rental_after_sales_case
set case_status = #{toStatus},
    finish_time = case when #{toStatus} = 1 then now() else finish_time end,
    update_by = #{operatorId},
    update_time = now(),
    remark = coalesce(#{remark}, remark)
where tenant_id = #{tenantId}
  and member_id = #{memberId}
  and case_no = #{caseNo}
  and case_status = #{fromStatus}
  and is_delete = 0

update ry_business.ry_rental_after_sales_case
set platform_ticket_no = #{platformTicketNo},
    update_by = #{operatorId}, update_time = now()
where tenant_id = #{tenantId}
  and member_id = #{memberId}
  and case_id = #{caseId}
  and is_delete = 0

mapper.select:
select event_type as eventType, from_status as fromStatus, to_status as toStatus,
       content, operator_name as operatorName, create_time as createTime
from ry_business.ry_rental_after_sales_event
where tenant_id = #{tenantId}
  and member_id = #{memberId}
  and case_id = #{caseId}
  and is_delete = 0
order by create_time asc, event_id asc

select evidence_type as evidenceType, file_url as fileUrl, file_name as fileName,
       file_mime as fileMime, description, operator_name as operatorName,
       create_time as createTime
from ry_business.ry_rental_after_sales_evidence
where tenant_id = #{tenantId}
  and member_id = #{memberId}
  and case_id = #{caseId}
  and is_delete = 0
order by create_time asc, evidence_id asc
